import{_ as l,h as o,i as e,c as i,v as r,p as s,x as n,m,e as d,S as p}from"./chunks/framework.Dvtg8yj2.js";const u=JSON.parse('{"title":"Transformer-XL","description":"","frontmatter":{"title":"Transformer-XL","date":"2026-09-03T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/transformer-xl.md","filePath":"llm/transformer-xl.md","lastUpdated":1788454257000}'),E={name:"llm/transformer-xl.md"};function h(B,a,f,c,T,A){const t=o("Mermaid");return e(),i("div",null,[a[1]||(a[1]=r('<h1 id="transformer-xl" tabindex="-1">Transformer-XL <a class="header-anchor" href="#transformer-xl" aria-label="Permalink to &quot;Transformer-XL&quot;">​</a></h1><div class="epigraph"><p>段与段之间不再切断隐状态：当前段的注意力可以读上一截冻结的记忆，相对位置则让这种读取在下标重启之后仍然合法。</p><footer>—— Dai et al., Transformer-XL, ACL 2019</footer></div><p>vanilla Transformer 语言模型把语料切成固定块，块与块之间没有隐状态传递，上下文在边界上碎掉。Dai、Yang、Yang、Carbonell、Le 与 Salakhutdinov 的 Transformer-XL 给出两件配套的东西：<strong>段级循环</strong>（把上一层、上一段的激活当记忆）和一套<strong>相对位置打分</strong>，使记忆里的位置不会因为每段从零编号而错乱。后继的 <a href="/llm/compressive-transformer">压缩记忆</a> 在 XL 的无损记忆之外再加压实槽，那是另一篇；本篇只写 2019 年原文的贡献、它如何度量「有效上下文」，以及它不是无限记忆。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>语言模型需要跨过远大于训练块长的依赖：维基文章的指代、小说里的人物、代码里的定义。把块长 \\(n\\) 加大，注意力按 \\(n^2\\) 涨，很快顶到 2019 年的显存。若保持 \\(n\\) 不大、块与块独立，则块首位置看不见块尾之前的任何 token，评估困惑度时还会在每块开头重复「冷启动」。这就是上下文碎片化。RNN 没有这个问题，因为它把状态压缩成一个向量传下去，但那正是 Transformer 想摆脱的递推瓶颈。</p><p>XL 要的是折中：计算图仍以段为单位并行，段与段之间只传递一截已经算好的激活，当作只读记忆。传递一旦发生，位置编码若仍用绝对下标，上一段的位置 \\(1\\ldots n\\) 会与当前段的 \\(1\\ldots n\\) 撞车。所以循环和相对位置必须一起出场；只做其中一件，记忆会读错距离。</p><h3 id="段间断裂" tabindex="-1">段间断裂 <a class="header-anchor" href="#段间断裂" aria-label="Permalink to &quot;段间断裂&quot;">​</a></h3><p>独立分块训练等于每 \\(n\\) 个 token 强制一个注意力隔断。层数再深，信息也不能跳到段外，因为根本没有边。评测若同样分块、不带记忆，困惑度会系统性高估长程模型、低估「会跨段」的模型。原文因此同时改训练与评测协议：评测时滑动窗口并带上记忆，使每个 token 的条件上下文尽量长。比较 XL 与 vanilla 时，必须确认基线是不是也在同一协议下评，否则数字不可比。</p><p><span class="marginnote">「XL」不是把窗口开到超长再做满注意力。当前段长度仍然有限，二次项写在 \\(n\\times(n+m)\\) 上，\\(m\\) 是记忆长度。它延长的是 <em>可复用的过去激活</em>，不是单次 \\(n\\)。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>训练时把序列分成段。算第 \\(\\tau\\) 段第 \\(\\ell\\) 层时，键值来自当前段激活与第 \\(\\tau-1\\) 段第 \\(\\ell\\) 层（或按实现来自上一段同层）缓存下来的记忆 \\(M\\)，查询只来自当前段。记忆上停梯度：不把 BPTT 展开进更早的段，训练才不会随文档无限变长。多层堆叠后，第 \\(\\ell\\) 层的记忆间接携带更早段、更浅层的信息，论文用「有效上下文 ≈ 层数 × 记忆长度」来描述这条沿深度的阶梯，而不是声称 \\(m\\) 本身等于历史长度。</p><p>相对位置用来替换绝对正弦或位置表。打分拆成内容项与位置项：查询与键的内容点积、查询对相对距离嵌入的项、以及与内容无关的全局偏置。这样，同一个相对偏移 \\(\\Delta\\) 在段边界两侧含义一致，记忆里的 token 不必重新编号成连续绝对下标。具体四项公式以 Dai 等论文为准；它与后来的 <a href="/llm/alibi">ALiBi</a>（距离线性偏置、不学嵌入）、<a href="/llm/rope">RoPE</a>（旋转 QK）不是同一参数化，不要把 XL 的相对项写成 RoPE 的先驱公式。</p>',12)),(e(),s(p,null,{default:n(()=>[d(t,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20LR%0A%20%20S1%5B%22%E4%B8%8A%E4%B8%80%E6%AE%B5%E6%BF%80%E6%B4%BB%22%5D%20--%3E%20MEM%5B%22%E5%86%BB%E7%BB%93%E8%AE%B0%E5%BF%86%20M%22%5D%0A%20%20S2%5B%22%E5%BD%93%E5%89%8D%E6%AE%B5%22%5D%20--%3E%20Q%5B%22%E6%9F%A5%E8%AF%A2%22%5D%0A%20%20MEM%20--%3E%20ATT%5B%22%E7%9B%B8%E5%AF%B9%E4%BD%8D%E7%BD%AE%E6%B3%A8%E6%84%8F%E5%8A%9B%22%5D%0A%20%20Q%20--%3E%20ATT%0A%20%20ATT%20--%3E%20OUT%5B%22%E5%BD%93%E5%89%8D%E6%AE%B5%E8%BE%93%E5%87%BA%22%5D%0A%20%20OUT%20--%3E%20NEXT%5B%22%E5%86%99%E5%85%A5%E4%B8%8B%E4%B8%80%E6%AE%B5%E7%9A%84%E8%AE%B0%E5%BF%86%22%5D%0A"})]),fallback:n(()=>[...a[0]||(a[0]=[m(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=r('<h3 id="段级循环与停梯度记忆" tabindex="-1">段级循环与停梯度记忆 <a class="header-anchor" href="#段级循环与停梯度记忆" aria-label="Permalink to &quot;段级循环与停梯度记忆&quot;">​</a></h3><p>记忆是缓存的隐状态，不是外部分词级 KV 的现代实现细节，但思想相同：过去已经算过的表示拿来当键值，不再重算。停梯度意味着模型不能通过记忆把监督信号送到 \\(m\\) 个 token 之外的参数更新里；长程依赖主要靠表示本身在训练分布里学会被后来的段读取。这与「可学习的无限记忆」不同。实现上 \\(m\\) 可与 \\(n\\) 不等；\\(m\\) 越大，读得越远，显存与 \\(n\\times m\\) 项越贵。评测可以把 \\(m\\) 开到比训练更大，原文报告了这种不对称，但那是外推记忆长度，不是外推绝对正弦相位。</p><h3 id="相对位置的四项打分" tabindex="-1">相对位置的四项打分 <a class="header-anchor" href="#相对位置的四项打分" aria-label="Permalink to &quot;相对位置的四项打分&quot;">​</a></h3><p>四项里真正新的是：把相对偏移做成可学习的、与内容解耦的通道，并加上对「任意键」和「任意查询」的偏置，使模型可以学到「总是看最近」或「总是看某种内容」的头。没有相对项，循环记忆会在位置编码上自相矛盾。没有循环，相对项只是一种绝对编码的替代，解决不了段间无边。原文的消融应被读成「两件套」，而不是两个独立 trick 的菜单。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>有效上下文沿深度放大，是因为第 1 层的记忆只含上一段 token 的浅表示，第 2 层的记忆已经是「看过上一段」之后的表示，于是第 \\(L\\) 层理论上能触及约 \\(L\\) 段之前的信息。这是一条 <em>接力</em>，每跳有损。字符级 enwik8、词级 WikiText-103 上，论文用更长的评测窗口和可视化来支持「比同样块长的 Transformer 读得更远」。它不是针测，当时也还没有 128k 指令协议。</p><p>停梯度使优化稳定，也封死了真正的跨文档 BPTT。若需要梯度穿过压缩后的更早历史，那是 Compressive Transformer 用辅助重构去补的方向。XL 自己的主张更窄：在不把计算图拉成整篇文档的前提下，打破段边界。</p><p><span class="marginnote">把 XL 记忆理解成今天服务里的 KV 缓存，方向对、合同不对。KV 缓存是逐步解码的实现；XL 记忆是训练期就存在的段间接口，且按层缓存激活。现代 LM 训练通常仍切包、用注意力掩码，并不默认启用 XL 式停梯度记忆。</span></p><h3 id="有效上下文不是无限的" tabindex="-1">有效上下文不是无限的 <a class="header-anchor" href="#有效上下文不是无限的" aria-label="Permalink to &quot;有效上下文不是无限的&quot;">​</a></h3><p>\\(L\\cdot m\\) 是上界式的口算，不是保证每条依赖都活着。中间层若把早期记忆写成均匀噪声，深层读到的只是近期。记忆队列仍会丢掉 \\(m\\) 之外的无损激活——这正是压缩记忆要接手的问题。相对位置的最大偏移若在实现里被截断到某桶，更远的距离会撞进同一个桶，长程分辨力下降。原文在字符与词级建模上把块长推到当时的「长」，并不是为指令模型的针测设计的。</p><h2 id="边界与工程取舍" tabindex="-1">边界与工程取舍 <a class="header-anchor" href="#边界与工程取舍" aria-label="Permalink to &quot;边界与工程取舍&quot;">​</a></h2><p>主场是语言建模（enwik8、text8、WikiText-103、One Billion Word），不是编码器文档分类，也不是机器翻译交叉注意力。把它接到 BERT 式双向编码器，段级循环与因果记忆的故事要重写。相对位置增加了注意力打分的参数与实现复杂度，后来许多解码器改用 RoPE，并不表示 XL 的循环接口被 RoPE 替代——RoPE 不提供段间记忆。</p><p>硬件上，\\(n\\times(n+m)\\) 仍是稠密注意力，只是 \\(n\\) 可以较小。2019 年这能打过「把 \\(n\\) 开到 \\(n+m\\) 做满注意力」。2024 年的长上下文更多走更长 \\(n\\)、滑窗、线性核或检索，而不是默认在预训练里加 XL 记忆。作为思想，它仍然是「状态沿段传递」的标准引用；作为默认架构，它没有成为 LLaMA 一类稠密解码器的层规范。</p><p><span class="marginnote">复现困惑度时，必须对齐分词、记忆长度、评测是否跨段带记忆、以及是否用相对打分。只抄「把过去 KV 拼上」而仍用每段重启的绝对位置，会得到一种既不是 vanilla 也不是 XL 的中间体。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>Transformer-XL 的原文贡献是段级循环记忆加上相对位置打分，用来打破语言模型的块边界。</li><li>记忆停梯度，有效上下文靠层间接力放大，不是无限可微的历史。</li><li>相对四项与 ALiBi、RoPE 不是同一公式；循环与相对项须配套。</li><li>主场是字符/词级语言建模；压缩更早历史是后继工作。</li><li>评测协议必须带记忆，否则与 vanilla 分块比没有意义。</li><li>它延长的是可复用激活，不是把单次注意力改成线性。</li><li>出处：Dai et al., <em>Transformer-XL: Attentive Language Models Beyond a Fixed-Length Context</em>, ACL 2019。</li></ul>',16))])}const _=l(E,[["render",h]]);export{u as __pageData,_ as default};
